import { csrfSync } from 'csrf-sync';
const { csrfSynchronisedProtection } = csrfSync({
  getTokenFromRequest: (req) => req.body._csrf,
});

app.post('/profil', csrfSynchronisedProtection, (req, res) => {
  mettreAJourProfil(req.session.utilisateur, req.body);
  res.redirect('/profil');
});

app.post('/changer-mot-de-passe', (req, res) => {
  changerMotDePasse(req.session.utilisateur, req.body.passwordNew);
  res.redirect('/profil');
});

