import { csrfSync } from 'csrf-sync';
const { csrfSynchronisedProtection } = csrfSync({
  getTokenFromRequest: (req) => req.body._csrf,
});

// Analyseurs de corps EN PREMIER : getTokenFromRequest lit req.body._csrf,
// qui n'existe pas encore tant que le corps n'a pas ete analyse.
app.use(express.urlencoded({ extended: false }));
app.use(express.json());

// Pose globale, APRES les analyseurs de corps et AVANT les routes :
// toute route d'etat est couverte, y compris celles qui n'existent pas encore.
app.use(csrfSynchronisedProtection);

app.post('/profil', (req, res) => {
  mettreAJourProfil(req.session.utilisateur, req.body);
  res.redirect('/profil');
});

app.post('/changer-mot-de-passe', (req, res) => {
  changerMotDePasse(req.session.utilisateur, req.body.passwordNew);
  res.redirect('/profil');
});
